        return payload

    def _headers(self) -> dict[str, str]:
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        }
        if self.organization:
            headers["OpenAI-Organization"] = self.organization
        if self.project:
            headers["OpenAI-Project"] = self.project
        return headers


def send_prompt(prompt: str, **kwargs: Any) -> str:
    """Send a private text prompt using ``OPENAI_API_KEY`` and return the text."""
    client_keys = {"api_key", "base_url", "model", "timeout", "organization", "project"}
    client_kwargs = {key: kwargs.pop(key) for key in list(kwargs) if key in client_keys}
    return OpenAIClient(**client_kwargs).send_prompt(prompt, **kwargs)


def output_text(response: Mapping[str, Any]) -> str:
    """Extract assistant text from a Responses API JSON object."""
    direct = response.get("output_text")
    if isinstance(direct, str) and direct:
        return direct

    chunks: list[str] = []
    output = response.get("output")
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, Mapping):
                continue
            content = item.get("content")
            if not isinstance(content, list):
                continue
            for part in content:
                if not isinstance(part, Mapping):
                    continue
                text = part.get("text")
                if isinstance(text, str):
                    chunks.append(text)
                elif isinstance(text, Mapping) and isinstance(text.get("value"), str):
                    chunks.append(text["value"])
    combined = "".join(chunks).strip()
    if combined:
        return combined
    raise OpenAIError("OpenAI Responses API returned no output text.", payload=response)


def _decode_json(raw: bytes) -> Any:
    if not raw:
        return None
    try:
        return json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None


def _http_error_message(status: int, payload: Any) -> str:
    prefix = f"OpenAI Responses API request failed with HTTP {status}"
    if isinstance(payload, Mapping):
        error = payload.get("error")
        if isinstance(error, Mapping) and isinstance(error.get("message"), str):
            return f"{prefix}: {error['"'message']}\"
        if isinstance(error, str):
            return f\"{prefix}: {error}\"
    return f\"{prefix}.\"
